steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": {
      "issues": {
        "filter": {
          "title": {
            "contains": "Checkout crash on Safari"
          }
        },
        "nodes": {
          "id",
          "title",
          "identifier",
          "estimate",
          "url",
          "comments": {
            "nodes": {
              "id",
              "body",
              "user": {
                "name",
                "id"
              }
            }
          }
        }
      }
    }
  }'
